CREATE OR REPLACE FUNCTION public.checkin_score_on_ten(p_value int, p_hunger int, p_fatigue int, p_sleep_quality int, p_stress int, p_motivation int, p_soreness int, p_pain int, p_energy int, p_mood int) RETURNS numeric LANGUAGE sql IMMUTABLE SET search_path = public AS $$ SELECT CASE WHEN p_value IS NULL THEN NULL WHEN ((p_hunger IS NULL OR p_hunger BETWEEN 1 AND 5) AND (p_fatigue IS NULL OR p_fatigue BETWEEN 1 AND 5) AND (p_sleep_quality IS NULL OR p_sleep_quality BETWEEN 1 AND 5) AND (p_stress IS NULL OR p_stress BETWEEN 1 AND 5) AND (p_motivation IS NULL OR p_motivation BETWEEN 1 AND 5) AND (p_soreness IS NULL OR p_soreness BETWEEN 1 AND 5) AND (p_pain IS NULL OR p_pain BETWEEN 1 AND 5) AND (p_energy IS NULL OR p_energy BETWEEN 1 AND 5) AND (p_mood IS NULL OR p_mood BETWEEN 1 AND 5) AND (p_hunger IS NOT NULL OR p_fatigue IS NOT NULL OR p_sleep_quality IS NOT NULL OR p_stress IS NOT NULL OR p_motivation IS NOT NULL OR p_soreness IS NOT NULL OR p_pain IS NOT NULL OR p_energy IS NOT NULL OR p_mood IS NOT NULL)) THEN LEAST(10, p_value * 2) ELSE LEAST(10, GREATEST(0, p_value)) END $$; REVOKE ALL ON FUNCTION public.checkin_score_on_ten(int, int, int, int, int, int, int, int, int, int) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.checkin_score_on_ten(int, int, int, int, int, int, int, int, int, int) TO authenticated, service_role; CREATE TABLE IF NOT EXISTS public.nutrition_target_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, effective_from date NOT NULL DEFAULT CURRENT_DATE, calories numeric NOT NULL DEFAULT 0, protein numeric NOT NULL DEFAULT 0, carbs numeric NOT NULL DEFAULT 0, fat numeric NOT NULL DEFAULT 0, source text NOT NULL DEFAULT 'profile_update', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, effective_from)); CREATE INDEX IF NOT EXISTS nutrition_target_history_user_idx ON public.nutrition_target_history (user_id, effective_from DESC); ALTER TABLE public.nutrition_target_history ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Users read own target history" ON public.nutrition_target_history; CREATE POLICY "Users read own target history" ON public.nutrition_target_history FOR SELECT TO authenticated USING (user_id = (select auth.uid())); DROP POLICY IF EXISTS "Coaches read client target history" ON public.nutrition_target_history; CREATE POLICY "Coaches read client target history" ON public.nutrition_target_history FOR SELECT TO authenticated USING (public.is_coach_of(user_id)); GRANT SELECT ON TABLE public.nutrition_target_history TO authenticated; CREATE OR REPLACE FUNCTION public.record_nutrition_target_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF OLD.daily_calorie_target IS NOT DISTINCT FROM NEW.daily_calorie_target AND OLD.protein_target IS NOT DISTINCT FROM NEW.protein_target AND OLD.carbs_target IS NOT DISTINCT FROM NEW.carbs_target AND OLD.fat_target IS NOT DISTINCT FROM NEW.fat_target THEN RETURN NEW; END IF; INSERT INTO public.nutrition_target_history (user_id, effective_from, calories, protein, carbs, fat, source) VALUES (NEW.id, CURRENT_DATE, COALESCE(NEW.daily_calorie_target, 0), COALESCE(NEW.protein_target, 0), COALESCE(NEW.carbs_target, 0), COALESCE(NEW.fat_target, 0), 'profile_update') ON CONFLICT (user_id, effective_from) DO UPDATE SET calories = EXCLUDED.calories, protein = EXCLUDED.protein, carbs = EXCLUDED.carbs, fat = EXCLUDED.fat, source = EXCLUDED.source, created_at = now(); RETURN NEW; END; $$; DROP TRIGGER IF EXISTS trg_record_target_history ON public.user_profiles; CREATE TRIGGER trg_record_target_history AFTER UPDATE OF daily_calorie_target, protein_target, carbs_target, fat_target ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION public.record_nutrition_target_history(); INSERT INTO public.nutrition_target_history (user_id, effective_from, calories, protein, carbs, fat, source) SELECT id, CURRENT_DATE - 30, COALESCE(daily_calorie_target, 0), COALESCE(protein_target, 0), COALESCE(carbs_target, 0), COALESCE(fat_target, 0), 'backfill' FROM public.user_profiles WHERE COALESCE(daily_calorie_target, 0) > 0 ON CONFLICT (user_id, effective_from) DO NOTHING;
